rules_data = cells('W0::Rules', 'B30:D39')
costs_data = cells('W0::Leaf costs', 'E30:F32')

unit_costs = {row[0]: row[1] for row in costs_data}
rules = {}
for row in rules_data:
    parent, comp, mult = row[0], row[1], row[2]
    rules.setdefault(parent, []).append((comp, mult))

def get_costs(part):
    if part in unit_costs:
        return {part: unit_costs[part]}
    res = {}
    if part in rules:
        for comp, mult in rules[part]:
            sub = get_costs(comp)
            for k, v in sub.items():
                res[k] = res.get(k, 0) + v * mult
    return res

crate_costs = get_costs('Crate')
beacon_costs = get_costs('Beacon')

total_crate = sum(v * unit_costs[k] for k, v in crate_costs.items())
total_beacon = sum(v * unit_costs[k] for k, v in beacon_costs.items())

result = round(total_crate - total_beacon, 2)

